insert into public.places (id, name, category, region, area, rating, reviews, image, image_alt, gallery, about, facts, stay_hotel, stay_note, related, map_x, map_y, featured, sort) values
  ('kakum', 'Kakum National Park', 'Nature', 'Central', 'Central Region · 33 km north of Cape Coast', 4.8, 412, 'kakum 1.jpeg', 'Rope canopy walkway strung between trees above the rainforest at Kakum', array['kakum 1.jpeg', 'kakum 2.jpg', 'kakum.jpeg', 'kakum3.jpeg']::text[], array['Kakum protects one of the last stretches of undisturbed rainforest in southern Ghana, covering roughly 375 square kilometres of the Central Region. The park is best known for its canopy walkway, a series of rope bridges suspended between hardwood trees and crossed on foot around thirty metres above the forest floor.', 'Below the canopy the forest supports forest elephants, bongo antelope, several primate species and over two hundred kinds of bird. Most visitors come for the walkway and the guided ground trails, both of which start from the visitor centre at the park entrance near Abrafo.']::text[], '[{"label": "Getting there", "value": "Tro-tro or taxi from Cape Coast, roughly 45 minutes"}, {"label": "Canopy walk", "value": "Seven bridges, about 40 minutes end to end"}, {"label": "Guides", "value": "Compulsory on all trails, arranged at the visitor centre"}, {"label": "Best time", "value": "Early morning, before the tour groups arrive"}, {"label": "Bring", "value": "Closed shoes, water, insect repellent"}, {"label": "Nearby", "value": "Often combined with Cape Coast and Elmina in one day"}]'::jsonb, 'ridge-royal', '34 km away', array['cape-coast', 'elmina']::text[], 42.7, 87.7, true, 0),
  ('cape-coast', 'Cape Coast Castle', 'History', 'Central', 'Central Region · Cape Coast · UNESCO World Heritage Site', 4.7, 538, 'cape coast castle.jpeg', 'White stone walls of Cape Coast Castle facing the sea', array['cape coast castle.jpeg', 'cape coast castle 1.jpeg', 'capecoastcastle3.jpeg', 'capecoastcastle4.jpg']::text[], array['Cape Coast Castle began as a Swedish trading post in 1653 and passed through Danish and Dutch hands before the British took it in 1664 and made it the headquarters of their administration on the Gold Coast. For nearly two centuries it was one of the largest holding sites in the transatlantic slave trade.', 'The tour moves between the airy governor''s quarters above and the dungeons below, ending at the Door of No Return that opens onto the shore. It is a difficult visit and deliberately so. A museum on the upper floor covers Akan history and the wider trade.']::text[], '[{"label": "Getting there", "value": "Central Cape Coast, walkable from most of the town"}, {"label": "Tours", "value": "Guided only, departing on the hour"}, {"label": "Duration", "value": "About 90 minutes"}, {"label": "Museum", "value": "Included, on the upper floor"}, {"label": "Note", "value": "The dungeon section is confined and emotionally heavy"}, {"label": "Nearby", "value": "Elmina Castle is 13 km west along the coast road"}]'::jsonb, 'ridge-royal', '2 km away', array['elmina', 'kakum', 'fort-william']::text[], 45.3, 91.3, true, 1),
  ('elmina', 'Elmina Castle', 'History', 'Central', 'Central Region · Elmina · UNESCO World Heritage Site', 4.6, 391, 'elmina castle.jpg', 'Elmina Castle seen across the harbour', array['elmina castle.jpg', 'elmina4.jpg', 'elminacastle1.jpeg', 'elminacastle2.jpeg']::text[], array['Built by the Portuguese in 1482 as São Jorge da Mina, Elmina is the oldest surviving European building in sub-Saharan Africa. The Dutch captured it in 1637 and held it for over two centuries before ceding it to the British in 1872.', 'The whitewashed fort sits directly above a working fishing harbour, and the contrast between the two is part of the visit. Tours cover the courtyards, the church the Dutch built inside the walls, and the dungeons beneath.']::text[], '[{"label": "Getting there", "value": "13 km west of Cape Coast, about 25 minutes by taxi"}, {"label": "Tours", "value": "Guided only, departing regularly through the day"}, {"label": "Duration", "value": "About 75 minutes"}, {"label": "Harbour", "value": "The fishing port below is busiest in the early morning"}, {"label": "Note", "value": "Steep stairs and low doorways throughout"}, {"label": "Nearby", "value": "Cape Coast Castle and Kakum both make an easy same-day pairing"}]'::jsonb, 'coconut-grove', '4 km away', array['cape-coast', 'kakum', 'labadi']::text[], 43.3, 91.6, true, 2),
  ('nkrumah', 'Kwame Nkrumah Memorial Park', 'History', 'Greater Accra', 'Greater Accra · Central Accra · mausoleum and museum', 4.6, 286, 'kwame nkrumah.jpg', 'Kwame Nkrumah Memorial Park in Accra', array['kwame nkrumah.jpg', 'kwamenkrumah1.jpeg', 'kwamenkrumah2.jpeg', 'kwamenkrumah3.jpeg']::text[], array['The park stands on the old polo grounds where Kwame Nkrumah declared Ghana''s independence in March 1957. It now holds the mausoleum of Ghana''s first president and his wife Fathia, set behind a long avenue of fountains.', 'A museum below the monument covers Nkrumah''s life, his role in pan-Africanism, and the 1966 coup that removed him. Personal effects, photographs and correspondence are on display, alongside the original statue toppled during the coup.']::text[], '[{"label": "Getting there", "value": "Central Accra, near the Independence Arch"}, {"label": "Duration", "value": "About an hour including the museum"}, {"label": "Guides", "value": "Available at the entrance, worth taking"}, {"label": "Photography", "value": "Permitted in the grounds"}, {"label": "Best time", "value": "Late afternoon, when the heat drops"}, {"label": "Nearby", "value": "Independence Square and the National Museum are both close"}]'::jsonb, 'kempinski-accra', '1 km away', array['black-star-square', 'jamestown', 'labadi']::text[], 64.6, 83.6, true, 3),
  ('mole', 'Mole National Park', 'Wildlife', 'Savannah', 'Savannah Region · Near Damongo · Ghana''s largest national park', 4.7, 243, 'mole national park 1.jpeg', 'Elephants at a waterhole in Mole National Park', array['mole national park 1.jpeg', 'shai hills.jpg', 'kakum 1.jpeg', 'Lake-Volta-jpg.webp']::text[], array['Mole covers roughly 4,577 square kilometres of guinea savannah in northern Ghana, making it by far the country''s largest protected area. Elephants are the draw, and they are regularly seen at the waterholes below the escarpment where the park accommodation sits.', 'Unusually, Mole allows walking safaris with an armed ranger as well as vehicle drives. Buffalo, warthog, kob, roan antelope and several primate species are common; the park also records over three hundred bird species.']::text[], '[{"label": "Getting there", "value": "About two hours by road from Tamale to Damongo"}, {"label": "Safaris", "value": "Walking and vehicle drives, both ranger-led"}, {"label": "Best time", "value": "Dry season, roughly November to April, when animals gather at water"}, {"label": "Timing", "value": "Drives leave at dawn and late afternoon"}, {"label": "Stay", "value": "Book accommodation inside the park well ahead"}, {"label": "Bring", "value": "Neutral clothing, binoculars, sun protection"}]'::jsonb, 'zaina-lodge', 'in the park', array['larabanga', 'salaga', 'kintampo']::text[], 34.4, 28.3, true, 4),
  ('aburi', 'Aburi Botanical Gardens', 'Nature', 'Eastern', 'Eastern Region · Akuapem Hills · 30 km north of Accra', 4.5, 198, 'aburi.jpg', 'Terraced lawns and mature trees at Aburi Botanical Gardens', array['aburi.jpg', 'kwame nkrumah.jpg', 'shai hills.jpg', 'wli waterfalls.jpeg']::text[], array['Opened in 1890 on the site of a former sanatorium, Aburi covers around 64 hectares of the Akuapem ridge. The avenue of royal palms at the entrance is the best-known feature, but the collection runs to hundreds of species across the terraces.', 'The hills sit several hundred metres above Accra and are noticeably cooler, which is most of the reason city residents come up at weekends. Craft stalls line the road into town, and the drive up through Peduase is worth the trip on its own.']::text[], '[{"label": "Getting there", "value": "About an hour from Accra by road, longer in traffic"}, {"label": "Duration", "value": "Two hours is comfortable"}, {"label": "Terrain", "value": "Gentle slopes and paved paths"}, {"label": "Best time", "value": "Weekday mornings, when it is quiet"}, {"label": "Nearby", "value": "Woodcarving stalls along the Aburi road"}, {"label": "Bring", "value": "A light layer — it is cooler than Accra"}]'::jsonb, 'tang-palace', '32 km away', array['boti-falls', 'shai', 'nkrumah']::text[], 64.9, 80.7, false, 5),
  ('wli', 'Wli Waterfalls', 'Nature', 'Volta', 'Volta Region · Agumatsa Reserve · near Hohoe', 4.8, 221, 'wli waterfalls.jpeg', 'Water falling down a cliff face into a pool at Wli', array['wli waterfalls.jpeg', 'afadjato.jpeg', 'Lake-Volta-jpg.webp', 'aburi.jpg']::text[], array['Wli is the highest waterfall in Ghana and among the highest in West Africa, dropping in stages down a cliff on the Togo border. The lower falls are reached by a level 45-minute walk through the Agumatsa reserve, crossing the river several times on footbridges.', 'The upper falls take a much harder climb of two to three hours up the escarpment, and reward it with a view over both countries. Thousands of fruit bats roost on the cliff face above the lower pool, and the sound carries a long way.']::text[], '[{"label": "Getting there", "value": "About 20 km from Hohoe, then a short drive to the reserve gate"}, {"label": "Lower falls", "value": "45 minutes each way, mostly flat"}, {"label": "Upper falls", "value": "Two to three hours each way, steep and unshaded in places"}, {"label": "Guides", "value": "Compulsory, arranged at the gate"}, {"label": "Swimming", "value": "Allowed in the lower pool"}, {"label": "Best time", "value": "Rainy season for volume, dry season for the trail"}]'::jsonb, 'wli-water-heights', 'near the falls', array['afadjato', 'tafi-atome', 'lake-volta']::text[], 79.3, 62.5, false, 6),
  ('shai', 'Shai Hills Resource Reserve', 'Wildlife', 'Greater Accra', 'Greater Accra · Near Doryumu · 50 km from Accra', 4.7, 164, 'shai hills.jpg', 'Rock outcrops rising from grassland at Shai Hills', array['shai hills.jpg', 'labadi beach.jpg', 'kwame nkrumah.jpg', 'mole national park 1.jpeg']::text[], array['Shai Hills is the closest wildlife reserve to Accra, a stretch of grassland and inselbergs covering around 51 square kilometres. Olive baboons are everywhere and unbothered by visitors; kob, bushbuck and introduced zebra are also present.', 'The hills themselves hold caves once occupied by the Shai people before their removal in 1892, and several are open to visitors with a guide. The rock outcrops are climbable and give a long view across the Accra plains.']::text[], '[{"label": "Getting there", "value": "About 90 minutes from central Accra on the Akosombo road"}, {"label": "Activities", "value": "Game drives, cave visits, rock climbing, birdwatching"}, {"label": "Guides", "value": "Required for the caves and hills"}, {"label": "Baboons", "value": "Keep food out of sight — they will take it"}, {"label": "Duration", "value": "Half a day is enough"}, {"label": "Best time", "value": "Early morning for wildlife"}]'::jsonb, 'tang-palace', '48 km away', array['labadi', 'nkrumah', 'mole']::text[], 69.6, 79.6, false, 7),
  ('labadi', 'Labadi Beach', 'Beach', 'Greater Accra', 'Greater Accra · La, Accra · also called La Pleasure Beach', 4.6, 502, 'labadi beach.jpg', 'Wide sand beach with palms at Labadi', array['labadi beach.jpg', 'kwame nkrumah.jpg', 'shai hills.jpg', 'elmina castle.jpg']::text[], array['Labadi is the busiest beach in Ghana and the most reliably lively stretch of the Accra coast. Weekends bring live highlife and reggae bands, drumming groups, horse riding along the sand and a steady run of food stalls behind the beach.', 'It is a social beach rather than a quiet one. The surf has a strong undertow and swimming is best kept close to shore. Several hotels along the strip maintain their own sections with loungers and calmer crowds.']::text[], '[{"label": "Getting there", "value": "About 20 minutes east of central Accra"}, {"label": "Entry", "value": "A gate fee applies, higher at weekends"}, {"label": "Weekends", "value": "Live music from the afternoon onwards"}, {"label": "Swimming", "value": "Strong undertow — stay near the shore"}, {"label": "Food", "value": "Grilled tilapia and kelewele from the stalls behind the sand"}, {"label": "Best time", "value": "Sunday afternoon for atmosphere, weekday morning for quiet"}]'::jsonb, 'labadi-beach-hotel', 'beachfront', array['ada-foah', 'jamestown', 'black-star-square']::text[], 65.9, 84.4, false, 8),
  ('afadjato', 'Mount Afadjato', 'Nature', 'Volta', 'Volta Region · Liati Wote · the highest peak in Ghana', 4.9, 147, 'afadjato.jpeg', 'Mount Afadjato rising above the treeline', array['afadjato.jpeg', 'wli waterfalls.jpeg', 'Lake-Volta-jpg.webp', 'aburi.jpg']::text[], array['Mount Afadja, usually called Afadjato, rises to about 885 metres on the Ghana–Togo border and is the highest point in the country. The climb starts from the village of Liati Wote, where the community runs the trail and provides guides.', 'It is steep rather than long — most people reach the summit in 90 minutes to two hours. The last section is a scramble through scrub. On a clear morning the view runs across the Volta hills and well into Togo.']::text[], '[{"label": "Getting there", "value": "From Hohoe to Liati Wote, then the trail starts in the village"}, {"label": "Climb", "value": "90 minutes to two hours up, about an hour down"}, {"label": "Difficulty", "value": "Steep and unshaded in places — take more water than you think"}, {"label": "Guides", "value": "Arranged in the village, fees support the community"}, {"label": "Best time", "value": "Start at first light, before the heat"}, {"label": "Nearby", "value": "Tagbo Falls is a short walk from the same village"}]'::jsonb, 'wli-water-heights', '25 km away', array['wli', 'lake-volta', 'aburi']::text[], 78.8, 64.3, false, 9),
  ('lake-volta', 'Lake Volta', 'Nature', 'Volta', 'Volta Region · Akosombo and north · the world''s largest reservoir by area', 4.8, 176, 'Lake-Volta-jpg.webp', 'Boats on the water at Lake Volta', array['Lake-Volta-jpg.webp', 'wli waterfalls.jpeg', 'afadjato.jpeg', 'shai hills.jpg']::text[], array['Lake Volta was created by the Akosombo Dam in 1965 and covers around 8,500 square kilometres, making it the largest man-made reservoir in the world by surface area. It stretches north from Akosombo through much of eastern Ghana.', 'Most visitors experience it from the Akosombo end, where boat cruises run on the lower lake and the dam itself can be viewed from the overlook. A passenger ferry also runs the length of the lake to Yeji, a long journey through country few tourists see.']::text[], '[{"label": "Getting there", "value": "Akosombo is about two hours from Accra by road"}, {"label": "Cruises", "value": "Day and sunset boats run from the Akosombo jetty"}, {"label": "Ferry", "value": "A long-haul service runs north to Yeji"}, {"label": "Dam", "value": "Viewable from the overlook; access is restricted"}, {"label": "Best time", "value": "Late afternoon, for the light on the water"}, {"label": "Nearby", "value": "Boti Falls and the Akosombo hotels"}]'::jsonb, 'volta-hotel', 'by the jetty', array['akosombo-dam', 'boti-falls', 'afadjato']::text[], 65.0, 69.5, false, 10),
  ('kintampo', 'Kintampo Waterfalls', 'Nature', 'Bono East', 'Bono East Region · 4 km north of Kintampo', 4.6, 188, 'commons:Kintampo_waterfall_level_3.jpg', 'Water spilling over rock steps into a pool at Kintampo Waterfalls', array['commons:Kintampo_waterfall_level_3.jpg', 'commons:Kintampo_Waterfalls.JPG']::text[], array['Kintampo Waterfalls is a chain of cascades on the Pumpum River, a tributary of the Black Volta, set in forest just outside Kintampo town. The water drops in stages, the largest about 25 metres, for a total fall of roughly 70 metres. In colonial times it was known as Sanders Falls, and it has been a tourist site since 1992.', 'The site closed after a storm in 2017 brought a tree down on visitors, and reopened in 2019 with new safety work and a canopy walkway. It sits right on the Kumasi to Tamale highway, which makes it the natural rest stop on any road trip north.']::text[], '[{"label": "Getting there", "value": "On the Kumasi to Tamale road, a short taxi ride from Kintampo"}, {"label": "Steps", "value": "The lowest fall is 173 steps down and 151 back up"}, {"label": "Canopy walk", "value": "Added when the site reopened in 2019"}, {"label": "Best time", "value": "May to October for volume, November to March for clearer water"}, {"label": "Swimming", "value": "Allowed in the lower pool when the guides say it is safe"}, {"label": "Nearby", "value": "Boabeng-Fiema Monkey Sanctuary is about an hour south"}]'::jsonb, 'golden-tulip', '210 km away', array['boabeng-fiema', 'larabanga', 'bosomtwe']::text[], 37.1, 48.5, true, 11),
  ('bosomtwe', 'Lake Bosomtwe', 'Nature', 'Ashanti', 'Ashanti Region · 30 km southeast of Kumasi', 4.5, 231, 'commons:Lake_Bosumtwi,_Ghana.jpg', 'Lake Bosomtwe ringed by forested crater walls', array['commons:Lake_Bosumtwi,_Ghana.jpg']::text[], array['Lake Bosomtwe is Ghana''s only natural lake, filling a meteorite crater about 10.5 kilometres across that formed roughly a million years ago. The lake covers around 49 square kilometres, reaches 81 metres at its deepest, and has no river flowing out of it.', 'About thirty villages sit around the shore. The Asante regard the lake as sacred, and fishermen traditionally paddle out lying on wooden planks rather than in boats. Abono is the main village for visitors, with guesthouses, canoe trips and walks along the crater rim.']::text[], '[{"label": "Getting there", "value": "About 45 minutes from Kumasi by road to Abono"}, {"label": "Activities", "value": "Canoe rides, swimming, crater-rim hikes, cycling round the lake"}, {"label": "Tradition", "value": "Fishing from padua planks instead of boats"}, {"label": "Duration", "value": "A day trip, or an overnight to see sunrise on the water"}, {"label": "Best time", "value": "Dry season, roughly November to March"}, {"label": "Nearby", "value": "Manhyia Palace in Kumasi on the way back"}]'::jsonb, 'paradise-bosomtwe', 'on the lakeshore', array['manhyia', 'kintampo']::text[], 42.3, 71.2, false, 12),
  ('manhyia', 'Manhyia Palace Museum', 'Culture', 'Ashanti', 'Ashanti Region · Kumasi · seat of the Asantehene', 4.5, 164, 'commons:Manhyia_Palace_Museum_(Kumasi,_Ghana_2017).jpg', 'The white colonial-era building of the Manhyia Palace Museum in Kumasi', array['commons:Manhyia_Palace_Museum_(Kumasi,_Ghana_2017).jpg', 'commons:Manhyia_Palace_Entrance.jpg']::text[], array['Manhyia is the seat of the Asantehene, king of the Asante. The British put up the original building in 1925, after destroying the earlier palace, and it served as the royal residence until a new palace was built beside it.', 'The old palace opened as a museum in August 1995. Inside are royal furniture, a bronze head of Prempeh II, an early map of the Asante kingdom and life-sized wax figures of past kings and queens, with statues of former rulers in the courtyard.']::text[], '[{"label": "Getting there", "value": "Northern Kumasi, a short taxi ride from the centre"}, {"label": "Tours", "value": "Guided, through the old palace rooms"}, {"label": "Duration", "value": "About an hour"}, {"label": "Photography", "value": "Usually restricted inside — ask at the desk"}, {"label": "Festivals", "value": "Akwasidae ceremonies at the palace follow the Akan calendar"}, {"label": "Nearby", "value": "Kejetia Market and Lake Bosomtwe"}]'::jsonb, 'golden-tulip', '3 km away', array['bosomtwe', 'kintampo']::text[], 38.5, 68.3, false, 13),
  ('boabeng-fiema', 'Boabeng-Fiema Monkey Sanctuary', 'Wildlife', 'Bono East', 'Bono East Region · near Nkoranza', 4.4, 97, 'commons:Boabeng_Fiema_monkey_sanctuary_3.jpg', 'A monkey in the trees at Boabeng-Fiema', array['commons:Boabeng_Fiema_monkey_sanctuary_3.jpg', 'commons:MONKEYS_AT_BOABENG-FIEMA_MONKEY_SANCTUARY.jpg']::text[], array['Boabeng and Fiema are two neighbouring villages that share a 4.4 square kilometre patch of forest with around 700 monkeys, mostly Campbell''s mona and black-and-white colobus. People here have treated the monkeys as sacred for generations.', 'Hunting them is forbidden, and when a monkey dies it is given a funeral and buried in its own cemetery. The monkeys move freely through the villages, and guided walks take you into the forest where the colobus troops live.']::text[], '[{"label": "Getting there", "value": "From Nkoranza by taxi, or off the Kintampo road"}, {"label": "Guides", "value": "Arranged at the visitor centre"}, {"label": "Rule", "value": "Do not feed the monkeys"}, {"label": "Duration", "value": "One to two hours"}, {"label": "Best time", "value": "Early morning, when the troops are most active"}, {"label": "Nearby", "value": "Kintampo Waterfalls is about an hour north"}]'::jsonb, 'golden-tulip', '160 km away', array['kintampo', 'tafi-atome']::text[], 36.6, 53.8, false, 14),
  ('larabanga', 'Larabanga Mosque', 'History', 'Savannah', 'Savannah Region · near the Mole park gate', 4.6, 142, 'commons:Larabanga_Mosque_Ghana.jpg', 'The whitewashed mud walls and wooden spikes of Larabanga Mosque', array['commons:Larabanga_Mosque_Ghana.jpg', 'commons:Larabanga_Mosque_front_side.jpg']::text[], array['Larabanga Mosque is a small Sudanese-style mosque of mud and timber, said to date from 1421, which makes it the oldest mosque in Ghana. It is sometimes called the Mecca of West Africa.', 'The building is only about eight metres square, braced by twelve buttresses with wooden beams sticking out of the walls. It was damaged by a storm in 2002 and restored with help from the World Monuments Fund.']::text[], '[{"label": "Getting there", "value": "15 km north of Damongo, about 4 km from the Mole entrance"}, {"label": "Entry", "value": "Non-Muslims view from outside; a local guide shows you round"}, {"label": "Dress", "value": "Cover shoulders and knees"}, {"label": "Duration", "value": "Under an hour"}, {"label": "Also see", "value": "The Mystic Stone on the edge of the village"}, {"label": "Nearby", "value": "Easy to pair with a safari at Mole"}]'::jsonb, 'zaina-lodge', '8 km away', array['mole', 'salaga']::text[], 34.2, 32.3, true, 15),
  ('paga', 'Paga Crocodile Pond', 'Wildlife', 'Upper East', 'Upper East Region · Paga · on the Burkina Faso border', 4.4, 118, 'commons:Paga_Crocodile_Pond_(tourism).jpg', 'A crocodile resting on the bank of the pond at Paga', array['commons:Paga_Crocodile_Pond_(tourism).jpg', 'commons:Crocodiles_in_the_Paga_Ponds.JPG']::text[], array['The Chief''s Pond at Paga is home to crocodiles that the town considers sacred. Local belief holds that each crocodile is linked to a person in the community, so killing one is forbidden, and the legend behind this is several centuries old.', 'Because they have lived alongside people for so long, the crocodiles are unusually calm. Visitors buy a live chicken to feed them, and a guide will help you crouch beside one for a photograph.']::text[], '[{"label": "Getting there", "value": "About 40 km north of Bolgatanga by road"}, {"label": "Feeding", "value": "Chickens are sold at the pond"}, {"label": "Safety", "value": "Only approach with a guide"}, {"label": "Duration", "value": "About an hour"}, {"label": "Nearby", "value": "Pikworo Slave Camp, a short drive away"}, {"label": "Best time", "value": "Morning or late afternoon, out of the midday heat"}]'::jsonb, 'gariba-lodge', '170 km away', array['tongo-hills', 'gambaga']::text[], 48.3, 7.0, false, 16),
  ('nzulezo', 'Nzulezo Stilt Village', 'Culture', 'Western', 'Western Region · near Beyin · on Lake Tadane', 4.5, 136, 'commons:Nzulezo_stilt_village.jpg', 'Wooden houses on stilts above the water at Nzulezo', array['commons:Nzulezo_stilt_village.jpg']::text[], array['Nzulezo is a village built entirely on stilts and wooden platforms over Lake Tadane, home to more than 500 people. Houses, a school and a church all stand above the water, linked by a main boardwalk.', 'You reach it by dugout canoe, a trip of about an hour through reeds and raffia palms from Beyin. The village has been on UNESCO''s tentative World Heritage list since 2000.']::text[], '[{"label": "Getting there", "value": "Canoe from Beyin, about 5 km and an hour each way"}, {"label": "Sacred day", "value": "Thursday — the village does not receive visitors"}, {"label": "Duration", "value": "Half a day including the canoe ride"}, {"label": "Bring", "value": "Sun hat, water and something to keep your phone dry"}, {"label": "Fees", "value": "Paid at the visitor centre in Beyin"}, {"label": "Nearby", "value": "Fort Apollonia in Beyin"}]'::jsonb, 'lou-moon', '50 km away', array['ankasa', 'cape-three-points', 'busua']::text[], 20.2, 92.5, true, 17),
  ('akosombo-dam', 'Akosombo Dam', 'History', 'Eastern', 'Eastern Region · Akosombo · on the Volta River', 4.3, 104, 'commons:Akosombo_Dam_is_spilling_water,_Ghana.JPG', 'Water released through the spillway of the Akosombo Dam', array['commons:Akosombo_Dam_is_spilling_water,_Ghana.JPG', 'commons:Akosombo_Dam,_Akosombo_Panorama.jpg']::text[], array['Akosombo Dam was built between 1961 and 1965 to power Ghana''s aluminium industry. It is a rock-fill wall 660 metres long and 114 metres high, and it still supplies a large share of the country''s electricity.', 'Damming the Volta created Lake Volta, the largest reservoir in the world by surface area. The project displaced about 80,000 people, a cost still remembered in the towns along the shore.']::text[], '[{"label": "Getting there", "value": "About two hours from Accra by road"}, {"label": "Tours", "value": "Arranged through the Volta River Authority"}, {"label": "Photography", "value": "Restricted at the dam itself — ask first"}, {"label": "Views", "value": "The terrace of the Volta Hotel looks over the dam"}, {"label": "Combine with", "value": "A cruise on Lake Volta from the Akosombo jetty"}, {"label": "Best time", "value": "Late afternoon for the light"}]'::jsonb, 'volta-hotel', 'overlooks the dam', array['lake-volta', 'boti-falls', 'shai']::text[], 69.4, 74.3, false, 18),
  ('tongo-hills', 'Tongo Hills and Tengzug Shrine', 'Culture', 'Upper East', 'Upper East Region · south of Tongo', 4.5, 72, 'commons:Tongo_Hills_and_Tengzug_Shrine_(Ghana_2013).jpg', 'Granite boulders piled on the slopes of the Tongo Hills', array['commons:Tongo_Hills_and_Tengzug_Shrine_(Ghana_2013).jpg', 'commons:Tongo_hills_and_Tengzug_shrine.jpg']::text[], array['The Tongo Hills are a range of granite outcrops south of Tongo, where huge boulders are stacked into strange shapes. In the dry season the wind across the rocks makes a whistling sound.', 'The hills hold the Tengzug shrines, which are deeply sacred to the people who live here. A guided walk takes you through the village, between the boulders and up to viewpoints over the savannah.']::text[], '[{"label": "Getting there", "value": "About 30 minutes from Bolgatanga by road"}, {"label": "Guides", "value": "Arranged in Tengzug village"}, {"label": "Shrine visits", "value": "Visitors remove their shirts as a sign of respect"}, {"label": "Terrain", "value": "Rocky scrambles — wear proper shoes"}, {"label": "Duration", "value": "Half a day"}, {"label": "Nearby", "value": "Paga Crocodile Pond and the Bolgatanga basket market"}]'::jsonb, 'gariba-lodge', '180 km away', array['paga', 'gambaga']::text[], 53.9, 11.6, false, 19),
  ('cape-three-points', 'Cape Three Points', 'Beach', 'Western', 'Western Region · the southernmost point of Ghana', 4.5, 88, 'commons:Cape_Three_Points_Lighthouse_1875.jpg', 'The old lighthouse on the headland at Cape Three Points', array['commons:Cape_Three_Points_Lighthouse_1875.jpg']::text[], array['Cape Three Points is the southernmost tip of Ghana, a forested headland between the villages of Akwidaa and Princes Town. On a map it is said to be the land closest to where the equator meets the prime meridian.', 'The British built a lighthouse here in 1875 for ships crossing the Gulf of Guinea. Its ruins stand beside a taller lighthouse finished in 1925 that still works, and the coast on either side has some of the quietest beaches in the country.']::text[], '[{"label": "Getting there", "value": "From Takoradi via Agona Nkwanta; the last stretch is rough road"}, {"label": "Lighthouse", "value": "The keeper may let you climb for a small tip"}, {"label": "Beaches", "value": "Akwidaa and Cape Three Points village"}, {"label": "Swimming", "value": "Currents can be strong — ask locally"}, {"label": "Duration", "value": "A full day, or stay over at a beach lodge"}, {"label": "Nearby", "value": "Busua and Fort Metal Cross at Dixcove"}]'::jsonb, 'busua-beach-resort', '25 km away', array['busua', 'nzulezo', 'ankasa']::text[], 29.6, 96.4, false, 20),
  ('ankasa', 'Ankasa Conservation Area', 'Nature', 'Western', 'Western Region · near the Côte d''Ivoire border', 4.4, 54, 'commons:Shining-blue_kingfisher_(Alcedo_quadribrachys_quadribrachys)_Ankasa_2.jpg', 'A shining-blue kingfisher perched in the Ankasa forest', array['commons:Shining-blue_kingfisher_(Alcedo_quadribrachys_quadribrachys)_Ankasa_2.jpg', 'commons:Chestnut-breasted_nigrita_(Nigrita_bicolor_bicolor)_Ankasa.jpg']::text[], array['Ankasa covers about 500 square kilometres in the far southwest, joining Nini-Suhien National Park with the Ankasa Forest Reserve. It is the only protected area in Ghana inside the wet evergreen rainforest belt.', 'Forest elephants, bongo, leopards, chimpanzees and Diana monkeys live here, along with more than 800 plant species, over 600 kinds of butterfly and around 190 birds. Most visitors come to walk the trails and look for birds.']::text[], '[{"label": "Getting there", "value": "Off the Elubo road, west of Axim"}, {"label": "Guides", "value": "Required on all trails"}, {"label": "Wildlife", "value": "Birds and butterflies are easy; mammals are shy"}, {"label": "Bring", "value": "Rain jacket, insect repellent, closed shoes"}, {"label": "Best time", "value": "Dry season, roughly December to March"}, {"label": "Nearby", "value": "Nzulezo Stilt Village"}]'::jsonb, 'lou-moon', '60 km away', array['nzulezo', 'cape-three-points']::text[], 19.3, 88.6, false, 21),
  ('tafi-atome', 'Tafi Atome Monkey Sanctuary', 'Wildlife', 'Volta', 'Volta Region · 43 km south of Hohoe', 4.5, 126, 'commons:Mona-TafiAtome20354.JPG', 'A mona monkey sitting on a branch at Tafi Atome', array['commons:Mona-TafiAtome20354.JPG', 'commons:Mona-TafiAtome20426.JPG']::text[], array['Tafi Atome is a community-run sanctuary set up in 1993 to protect the village''s sacred grove. Its mona monkeys have long been seen locally as messengers of the gods.', 'Since the village stepped up protection in 1996 the monkey population has grown, and the forest''s birds and butterflies have recovered with it. New visitor facilities opened in 2020, and fees go back into the community.']::text[], '[{"label": "Getting there", "value": "About 230 km from Accra; turn off between Ho and Hohoe"}, {"label": "Tours", "value": "Guided walks into the grove"}, {"label": "Feeding", "value": "Bananas are offered under the guide''s direction"}, {"label": "Duration", "value": "About an hour"}, {"label": "Best time", "value": "Early morning or late afternoon"}, {"label": "Nearby", "value": "Wli Waterfalls and Mount Afadjato"}]'::jsonb, 'wli-water-heights', '60 km away', array['wli', 'afadjato', 'boabeng-fiema']::text[], 75.4, 65.4, false, 22),
  ('jamestown', 'Jamestown Lighthouse', 'History', 'Greater Accra', 'Greater Accra · Jamestown, old Accra', 4.3, 147, 'commons:Jamestown_Lighthouse_(Accra,_Ghana_2017).jpg', 'The red and white Jamestown Lighthouse above the rooftops of old Accra', array['commons:Jamestown_Lighthouse_(Accra,_Ghana_2017).jpg', 'commons:Jamestown_Lighthouse,_Accra.jpg']::text[], array['The red and white lighthouse in Jamestown, the oldest part of Accra, has guided ships into the city since 1932. It stands on the site of an earlier light from 1871 and rises about 28 metres.', 'From the top you look over the fishing harbour, the colourful canoes and the old British fort. The lanes below are home to Ga fishing families, boxing gyms and murals painted for the Chale Wote street art festival.']::text[], '[{"label": "Getting there", "value": "Central Accra, at the end of High Street"}, {"label": "Climb", "value": "A caretaker takes you up for a small fee"}, {"label": "Tours", "value": "Local guides run walking tours of Jamestown"}, {"label": "Best time", "value": "Late afternoon, when the boats come in"}, {"label": "Festival", "value": "Chale Wote street art festival, usually in August"}, {"label": "Nearby", "value": "Black Star Square and the Nkrumah Memorial Park"}]'::jsonb, 'kempinski-accra', '4 km away', array['black-star-square', 'nkrumah', 'labadi']::text[], 62.9, 85.3, false, 23),
  ('black-star-square', 'Black Star Square', 'History', 'Greater Accra', 'Greater Accra · Independence Avenue, Accra', 4.4, 203, 'commons:Black_Star_Square_and_Independence_Arch,_Accra,_Ghana.jpg', 'The Independence Arch and parade ground at Black Star Square', array['commons:Black_Star_Square_and_Independence_Arch,_Accra,_Ghana.jpg', 'commons:The_Black_Star_Gate.jpg']::text[], array['Black Star Square, also called Independence Square, was commissioned by Kwame Nkrumah and completed in 1961. Its stands seat around 30,000 people, making it one of the largest public squares in the world.', 'The square holds the Independence Arch and the Black Star Gate, whose star echoes the Black Star shipping line of Marcus Garvey. Ghana''s Independence Day parade takes place here every 6 March.']::text[], '[{"label": "Getting there", "value": "Central Accra, on the seafront"}, {"label": "Entry", "value": "Free to walk around outside events"}, {"label": "Events", "value": "Independence Day parade on 6 March"}, {"label": "Duration", "value": "30 minutes to an hour"}, {"label": "Best time", "value": "Early evening, when it cools down"}, {"label": "Nearby", "value": "Kwame Nkrumah Memorial Park is a short walk away"}]'::jsonb, 'kempinski-accra', '2 km away', array['nkrumah', 'jamestown', 'labadi']::text[], 64.2, 84.8, false, 24),
  ('ada-foah', 'Ada Foah', 'Beach', 'Greater Accra', 'Greater Accra · where the Volta meets the sea', 4.5, 179, 'commons:Beach_in_Ada_Foah.jpg', 'Palm trees along the sandy beach at Ada Foah', array['commons:Beach_in_Ada_Foah.jpg', 'commons:Treasure_Island,_Ada_Foah_(P1090934-Pano).jpg']::text[], array['Ada Foah is a coastal town at the mouth of the Volta River, known for the estuary islands and palm-lined sandbars where the river meets the Atlantic. Riverside chalets make it a favourite weekend escape from Accra.', 'Boats take you between the islands for swimming, fishing and sunset trips. The Danes built Fort Kongenstein here in 1783, and coastal erosion has left only part of it standing. The Asafotufiami festival is celebrated in the Ada area each August.']::text[], '[{"label": "Getting there", "value": "About two hours east of Accra by road"}, {"label": "Boats", "value": "For hire at the riverside harbour"}, {"label": "Swimming", "value": "Calmer on the river side than the ocean side"}, {"label": "Festival", "value": "Asafotufiami, first week of August"}, {"label": "History", "value": "Remains of Fort Kongenstein near the shore"}, {"label": "Best time", "value": "Weekdays, when it is quieter"}]'::jsonb, 'aqua-safari', 'on the estuary', array['labadi', 'shai', 'akosombo-dam']::text[], 79.9, 81.7, false, 25),
  ('fort-william', 'Fort William, Anomabu', 'History', 'Central', 'Central Region · Anomabu · UNESCO World Heritage Site', 4.3, 64, 'commons:Fort_William,_Anomabo_8.jpg', 'The white walls of Fort William at Anomabu', array['commons:Fort_William,_Anomabo_8.jpg', 'commons:Fort_William,_Anomabo_12.jpg']::text[], array['Fort William was begun in 1753 by the British Company of Merchants, after they blocked a French attempt to build on the same spot. It was designed by John Apperly, its first governor, and completed by Richard Brew in 1760.', 'Like the castles at Cape Coast and Elmina, it was used in the Atlantic slave trade, and in 1979 it was added to UNESCO''s World Heritage List with the other forts of the Ghana coast. It is quieter than the big castles and well preserved.']::text[], '[{"label": "Getting there", "value": "About 17 km east of Cape Coast on the coast road"}, {"label": "Tours", "value": "Guided by the caretaker"}, {"label": "Duration", "value": "About 45 minutes"}, {"label": "Note", "value": "Holding cells are confined and dark"}, {"label": "Best time", "value": "Morning, before the heat"}, {"label": "Nearby", "value": "Cape Coast Castle and Kakum"}]'::jsonb, 'ridge-royal', '18 km away', array['cape-coast', 'elmina', 'kakum']::text[], 47.5, 90.3, false, 26),
  ('busua', 'Busua Beach', 'Beach', 'Western', 'Western Region · 30 km west of Takoradi', 4.6, 211, 'commons:Surfers_Surfing_at_Busua_Beach_in_Western_region,_Ghana.jpg', 'Surfers riding waves off Busua Beach', array['commons:Surfers_Surfing_at_Busua_Beach_in_Western_region,_Ghana.jpg', 'commons:Busua_Beach_Resort_setting_in_Western_region,_Ghana.jpg']::text[], array['Busua is a fishing village with a long sandy beach on the Gulf of Guinea. The water is calmer than most of Ghana''s coast, and it has become the country''s main spot for learning to surf.', 'Fishing for tuna and marlin still drives the village. A 25-minute walk west brings you to Dixcove and the old British Fort Metal Cross, and to the east is the Dutch Fort Batenstein.']::text[], '[{"label": "Getting there", "value": "Paved road from Takoradi, about 45 minutes"}, {"label": "Surfing", "value": "Board hire and lessons on the beach"}, {"label": "Walks", "value": "Dixcove and Fort Metal Cross, 25 minutes west"}, {"label": "Food", "value": "Fresh fish and lobster at the beach shacks"}, {"label": "Best time", "value": "November to March for the driest weather"}, {"label": "Nearby", "value": "Cape Three Points"}]'::jsonb, 'busua-beach-resort', 'beachfront', array['cape-three-points', 'nzulezo', 'ankasa']::text[], 32.5, 95.6, false, 27),
  ('salaga', 'Salaga Slave Market', 'History', 'Savannah', 'Savannah Region · Salaga, East Gonja', 4.2, 41, 'commons:Salaga_Slave_Well_in_Northern_Ghana.jpg', 'One of the wells where captives were washed at Salaga', array['commons:Salaga_Slave_Well_in_Northern_Ghana.jpg', 'commons:Salaga_slave_museum_in_Northern_Ghana_03.jpg']::text[], array['Salaga was the largest slave market in the region during the 18th and 19th centuries. Captives brought here were sold and then marched south to the coastal forts for export across the Atlantic.', 'The town was also a great trading centre for kola, and its mix of peoples earned it the name Timbuktu of the South. Today you can see the bathing site where captives were washed before sale, a baobab marking the old market and a small museum.']::text[], '[{"label": "Getting there", "value": "About three hours by road from Tamale"}, {"label": "Guides", "value": "Arranged locally — they explain each site"}, {"label": "Sites", "value": "Bathing site, market baobab and the slave museum"}, {"label": "Duration", "value": "Two hours"}, {"label": "Note", "value": "A sobering visit, best paired with Cape Coast"}, {"label": "Nearby", "value": "Larabanga Mosque and Mole"}]'::jsonb, 'gariba-lodge', '120 km away', array['larabanga', 'mole', 'cape-coast']::text[], 59.0, 42.0, false, 28),
  ('boti-falls', 'Boti Falls', 'Nature', 'Eastern', 'Eastern Region · northeast of Koforidua', 4.5, 196, 'boti falls.jpeg', 'Twin waterfalls dropping into a forest pool at Boti', array['boti falls.jpeg']::text[], array['Boti Falls is a pair of waterfalls side by side, separated by a rocky ledge. Local tradition calls them male and female, the larger one being male, and says a rainbow appears when the two join in the rainy season.', 'The water falls about 30 metres into a pool where visitors swim. The falls sit at the bottom of around 250 concrete steps in the Huhunya forest, and guides lead walks on to nearby rock formations.']::text[], '[{"label": "Getting there", "value": "About 30 minutes from Koforidua, 90 minutes or more from Accra"}, {"label": "Steps", "value": "About 250 down to the pool"}, {"label": "Entry", "value": "Includes a guided tour and hike"}, {"label": "Best time", "value": "June to August, when the falls merge"}, {"label": "Swimming", "value": "Allowed in the pool"}, {"label": "Nearby", "value": "Aburi Botanical Gardens and Akosombo"}]'::jsonb, 'volta-hotel', '50 km away', array['aburi', 'akosombo-dam', 'lake-volta']::text[], 64.2, 75.8, false, 29),
  ('gambaga', 'Gambaga Escarpment', 'Nature', 'North East', 'North East Region · Gambaga and Nakpanduri', 4.3, 38, 'commons:Gambaga_Escarpment_01.jpg', 'The long sandstone ridge of the Gambaga Escarpment over the plain', array['commons:Gambaga_Escarpment_01.jpg', 'commons:Gambaga_Escarpment_landscape.jpg']::text[], array['The Gambaga Escarpment is a sandstone ridge that runs for around 100 kilometres across northeastern Ghana, forming the raised northern edge of the Volta basin. It turns the White Volta west before the river bends south again.', 'Gambaga, once capital of the Mamprugu kingdom, sits beneath the cliffs. Nakpanduri, on top of the ridge, is the usual starting point for hikes, with wide views across the plains below.']::text[], '[{"label": "Getting there", "value": "From Tamale via Walewale to Gambaga"}, {"label": "Hiking", "value": "Start from Nakpanduri for the best views"}, {"label": "Guides", "value": "Ask in town — trails are not marked"}, {"label": "Best time", "value": "Early morning in the dry season"}, {"label": "Bring", "value": "Plenty of water and sun protection"}, {"label": "Nearby", "value": "Nalerigu, seat of the Nayiri"}]'::jsonb, 'gariba-lodge', '150 km away', array['tongo-hills', 'paga', 'mole']::text[], 63.2, 12.9, false, 30);
