insert into public.messages (room_id, author_name, body, created_at) values
  ('kakum', 'Kwabena', 'Has anyone visited Elmina Castle recently? Wondering how busy it gets.', date_trunc('day', now()) - interval '1 day' + interval '8 hours 41 minutes'),
  ('kakum', 'Ama', 'Went two weeks ago. Tours start on the hour and the 9am one was almost empty.', date_trunc('day', now()) - interval '1 day' + interval '8 hours 47 minutes'),
  ('kakum', 'Ama', 'Go on a weekday if you can. Saturdays are rough.', date_trunc('day', now()) - interval '1 day' + interval '8 hours 48 minutes'),
  ('kakum', 'Kofi', 'Good to know. Is it walkable from Cape Coast Castle or should I get a taxi?', date_trunc('day', now()) - interval '1 day' + interval '9 hours 2 minutes'),
  ('kakum', 'Yaw', 'Taxi. It is about 15km along the coast road, roughly GHS 40.', date_trunc('day', now()) - interval '1 day' + interval '9 hours 9 minutes'),
  ('kakum', 'Kofi', 'Perfect, thanks both.', date_trunc('day', now()) - interval '1 day' + interval '9 hours 11 minutes'),
  ('kakum', 'Ama', 'Do Kakum the same trip. It is 40 minutes inland and the canopy walk opens at 8.', date_trunc('day', now()) - interval '1 day' + interval '9 hours 14 minutes'),
  ('volta', 'Selasi', 'Wli was full of water last weekend. The lower falls trail was muddy but fine.', date_trunc('day', now()) - interval '1 day' + interval '7 hours 30 minutes'),
  ('volta', 'Kojo', 'Afadjato in the rainy season?', date_trunc('day', now()) - interval '1 day' + interval '8 hours 2 minutes'),
  ('accra', 'Esi', 'Anyone know a quiet spot near Labadi for Sunday?', date_trunc('day', now()) - interval '1 day' + interval '20 hours 15 minutes'),
  ('accra', 'Naa', 'Labadi was packed on Sunday', date_trunc('day', now()) - interval '1 day' + interval '21 hours 40 minutes'),
  ('mole', 'Fuseini', 'The 6:30 walking safari is the one to book.', date_trunc('day', now()) - interval '1 day' + interval '16 hours 50 minutes'),
  ('mole', 'Yaw', 'Saw elephants at the waterhole', date_trunc('day', now()) - interval '1 day' + interval '17 hours 22 minutes'),
  ('solo', 'Kweku', 'The STC bus to Tamale was comfortable, about 12 hours.', date_trunc('day', now()) - interval '1 day' + interval '13 hours 40 minutes'),
  ('solo', 'Efua', 'Anyone heading north in October?', date_trunc('day', now()) - interval '1 day' + interval '14 hours 5 minutes'),
  ('north', 'Abena', 'Is the road from Tamale to Damongo paved now?', date_trunc('day', now()) - interval '1 day' + interval '10 hours 58 minutes'),
  ('north', 'Musah', 'Tamale to Mole is about 2 hours', date_trunc('day', now()) - interval '1 day' + interval '11 hours 30 minutes');
